<template><div class="access-page"><div class="page-heading"><div><p class="eyebrow">ACCESS CONTROL</p><h1>下载配额与团队协作</h1><p>公开作品使用每日下载配额，团队资产通过邀请码加入并继承空间角色。</p></div></div><a-row :gutter="20"><a-col :xs="24" :lg="8"><a-card title="今日下载配额" :bordered="false"><div class="quota"><strong>{{ remaining }}</strong><span>/ {{ quota?.quotaLimit || 0 }} 次</span></div><a-progress :percent="percent" :show-info="false" status="active" /></a-card></a-col><a-col :xs="24" :lg="16"><a-card title="加入团队" :bordered="false"><a-input-search v-model:value="code" enter-button="兑换邀请码" placeholder="输入团队邀请码" @search="redeem" /></a-card></a-col></a-row></div></template>
<script setup lang="ts">import { computed, onMounted, ref } from 'vue'; import { message } from 'ant-design-vue'; import { getTodayQuota, redeemInvite } from '@/api/photoCommunity'; const quota=ref<any>(); const code=ref(''); const remaining=computed(()=>Math.max(0,(quota.value?.quotaLimit||0)-(quota.value?.usedCount||0))); const percent=computed(()=>quota.value?.quotaLimit?Math.round((quota.value.usedCount/quota.value.quotaLimit)*100):0); async function load(){const res:any=await getTodayQuota();if(res.data.code===0)quota.value=res.data.data} async function redeem(){if(!code.value.trim())return;const res:any=await redeemInvite({code:code.value.trim()});if(res.data.code===0){message.success('已加入团队');code.value=''}else message.error(res.data.message)} onMounted(load)</script>
<style scoped>.access-page{max-width:1000px;margin:0 auto}.page-heading{margin-bottom:28px}.eyebrow{color:#5a836d;letter-spacing:2px;font-size:12px;margin:0 0 10px}.page-heading h1{color:#20322e;margin:0 0 10px}.page-heading p{color:#748078}.access-page :deep(.ant-card){border:1px solid #e5ebe7;box-shadow:none;min-height:160px}.quota{display:flex;align-items:baseline;gap:8px;margin:12px 0 18px}.quota strong{font-size:38px;color:#355443}.quota span{color:#7a8780}</style>
